// Hand-drawn brush stamps extracted from a Photoshop .abr fantasy-cartography
// brush set (offline, embedded as base64 -- no network fetch, no CORS/canvas-taint
// issues when the app is opened directly via file://).

const STAMP_SOURCES = {
  peak_bold: { w: 160, h: 144, data: 'data:image/png;base64,' },
  tree_cluster: { w: 160, h: 147, data: 'data:image/png;base64,' },
  tree_starburst: { w: 90, h: 87, data: 'data:image/png;base64,' },
  compass: { w: 154, h: 160, data: 'data:image/png;base64,' },
  shield: { w: 53, h: 64, data: 'data:image/png;base64,' },
  pin: { w: 35, h: 85, data: 'data:image/png;base64,' },
  reed: { w: 88, h: 160, data: 'data:image/png;base64,' },
  dune: { w: 160, h: 47, data: 'data:image/png;base64,' },
  island: { w: 89, h: 160, data: 'data:image/png;base64,' },
  temple_dome: { w: 101, h: 98, data: 'data:image/png;base64,' },
  crack: { w: 155, h: 160, data: 'data:image/png;base64,' },
  hill_line: { w: 160, h: 74, data: 'data:image/png;base64,' },
  peak_single: { w: 160, h: 113, data: 'data:image/png;base64,' },
  castle_flag: { w: 87, h: 117, data: 'data:image/png;base64,' },
};

const STAMP_IMAGES = {};
const stampsReady = Promise.all(Object.entries(STAMP_SOURCES).map(([key, src]) => {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve();
    img.onerror = () => resolve();
    img.src = src.data;
    STAMP_IMAGES[key] = img;
  });
}));

const _tintedStampCache = new Map();

function getTintedStamp(key, color) {
  const cacheKey = key + '|' + color;
  let canvas = _tintedStampCache.get(cacheKey);
  if (canvas) return canvas;
  const img = STAMP_IMAGES[key];
  const src = STAMP_SOURCES[key];
  if (!img || !src) return null;
  canvas = document.createElement('canvas');
  canvas.width = src.w;
  canvas.height = src.h;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0, src.w, src.h);
  ctx.globalCompositeOperation = 'source-in';
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, src.w, src.h);
  _tintedStampCache.set(cacheKey, canvas);
  return canvas;
}

// Draws a stamp centered at the current ctx origin (caller translates/rotates first).
// `size` sets the stamp's longer side; the shorter side follows its natural aspect ratio.
function drawStamp(ctx, key, size, color) {
  const canvas = getTintedStamp(key, color);
  if (!canvas) return;
  const aspect = canvas.width / canvas.height;
  let w, h;
  if (aspect >= 1) { w = size; h = size / aspect; }
  else { h = size; w = size * aspect; }
  ctx.drawImage(canvas, -w / 2, -h / 2, w, h);
}
